<?php
namespace App\Policies; use App\Enums\UserRole; use App\Models\{Order, User}; class OrderPolicy { public function viewAny(User $user): bool { return true; } public function view(User $user, Order $order): bool { return in_array($user->role, [UserRole::Owner,UserRole::Admin], true) || $order->customer_id === $user->id || $order->worker_id === $user->id; } public function create(User $user): bool { return in_array($user->role, [UserRole::Owner,UserRole::Admin,UserRole::Customer], true); } public function update(User $user, Order $order): bool { return in_array($user->role, [UserRole::Owner,UserRole::Admin], true) || $order->customer_id === $user->id; } public function assign(User $user): bool { return in_array($user->role, [UserRole::Owner,UserRole::Admin], true); } public function progress(User $user, Order $order): bool { return in_array($user->role, [UserRole::Owner,UserRole::Admin], true) || $order->worker_id === $user->id; } }
